/** Teaching content for common topics. A topic matches a concept by keywords; each gives the explanation, key points and a worked example. */
export type Concept = { re: RegExp; title: string; explain: string; points: string[]; example: string };
const C = (re: RegExp, title: string, explain: string, points: string[], example: string): Concept => ({ re, title, explain, points, example });

export const CONCEPTS: Concept[] = [
  C(/digital literacy|digital ethic|digital media|image editing|audio editing|video editing|file and folder|electronic communication|emerging (trends|technolog)|technology in society|careers in digital|introduction to digital|practical project|artificial intelligence|cloud|social media|e-?commerce|database|spreadsheet|programming|web design|html/i, "Digital technologies in practice", "Digital literacy is the ability to find, evaluate, create and share information using technology responsibly. Organise files in folders with clear names and keep backups. Digital ethics covers honesty, respect for copyright, privacy and kindness online. Media editing follows a workflow: collect material, import it, arrange and edit (crop images, trim audio and video), add effects, export in a suitable format and share. Emerging technologies include artificial intelligence, cloud computing, robotics and the internet of things; careers range from software developer to network engineer and data analyst.", ["Cite sources and respect copyright.", "Back up important files in two places.", "Think before you post."], "To resize a photograph for a school website, open it in an image editor, choose Resize, keep the proportions locked, and export it as a JPEG."),
  C(/construction|loci|locus|bisector|perpendicular|compass and ruler|proofs? of theorem|riders|geometrical proof/i, "Constructions and proofs in geometry", "Constructions use only a ruler and compasses. To bisect an angle, draw an arc cutting both arms, then arcs from those points that meet; join the vertex to that intersection. To draw a perpendicular bisector, draw equal arcs from both ends of a line above and below it. A geometric proof gives statements with reasons, such as 'vertically opposite angles are equal' or 'angles on a straight line add up to 180°'.", ["Never erase construction arcs.", "State the theorem you are using at each step."], "To construct a 60° angle, draw an arc from the vertex, then an arc of the same radius from where it cuts the base, and join."),
  C(/subject of (a )?formula|change of subject|formulae|transposition/i, "Changing the subject of a formula", "To make a letter the subject, isolate it by doing the same operations to both sides in reverse order. Undo addition and subtraction first, then multiplication and division, then powers and roots. If the letter appears twice, collect those terms and factorise.", ["Treat the formula like an equation.", "Check by substituting numbers."], "Make r the subject of A = πr²: divide by π to get r² = A/π, then take the square root: r = √(A/π)."),
  C(/measures? of central tendency|mean, median|modal class|grouped data|cumulative frequency|ogive|quartile|standard deviation|dispersion|histogram/i, "Averages and spread of data", "For grouped data the mean = Σfx ÷ Σf, using class mid-points. The mode is the class with the highest frequency; the median is found from the cumulative frequency curve (ogive) at half the total. The range is largest minus smallest; the interquartile range = Q₃ − Q₁; the standard deviation measures how far values lie from the mean.", ["Use mid-points for grouped data.", "Histogram bar area is proportional to frequency."], "Classes 0–10, 10–20, 20–30 with frequencies 2, 5, 3 have mid-points 5, 15, 25 and mean (10 + 75 + 75) ÷ 10 = 16."),
  C(/modular arithmetic|logical reasoning|quantitative aptitude|number bases?|base two|binary|conversion of bases/i, "Number bases, modular arithmetic and logic", "In base n, place values are powers of n. To convert 1011₂ to base ten: 1×8 + 0×4 + 1×2 + 1×1 = 11. To convert from base ten, divide repeatedly by the base and read the remainders upward. In modular arithmetic we use the remainder after division: 17 ≡ 2 (mod 5). Logical reasoning uses statements, 'and', 'or', 'if … then' and truth tables to test arguments.", ["Binary uses only 0 and 1.", "Check conversions by converting back."], "13 ÷ 2 = 6 r 1; 6 ÷ 2 = 3 r 0; 3 ÷ 2 = 1 r 1; 1 ÷ 2 = 0 r 1; reading up gives 1101₂."),
  C(/embroidery|knitting|crochet|singing|rehearsal|the director|mosaic|introduction to arts|self-control|choir|voice production/i, "Creative arts skills", "Needle crafts: embroidery decorates cloth with stitches (running, back, satin, chain); knitting loops yarn with two needles; crochet uses a single hook. Always start with a simple pattern and keep an even tension. In music, breathe deeply, sit or stand straight and sing in tune with the group. In drama the director plans the play, guides the actors in rehearsal and manages time and the stage. Self-control and teamwork make any performance succeed.", ["Practise a little every day.", "Respect the work of others."], "A back stitch makes a firm line: bring the needle up one stitch ahead, then insert it at the end of the previous stitch."),
  C(/gas laws|boyle|charles|kinetic theory|pressure law|human eye|fields?\b|gravitational field|electric field|magnetic field|nucleus|radioactive|transmission system|communication system|satellite|telecommunication/i, "Gases, fields, the eye and communication", "Gas laws: Boyle's law says PV = constant at fixed temperature; Charles's law says V/T = constant at fixed pressure (T in kelvin); the pressure law says P/T = constant at fixed volume. A field is a region where a force acts: gravitational field strength g = F/m (about 10 N/kg on Earth). The human eye forms an inverted real image on the retina, and the brain interprets it. In a communication system a transmitter sends a signal through a channel to a receiver; satellites relay signals over long distances.", ["Always convert temperature to kelvin: K = °C + 273.", "Fields are shown by lines; closer lines mean stronger fields."], "A gas at 2 atm in 6 dm³ is compressed to 3 dm³ at constant temperature: P = 2 × 6 ÷ 3 = 4 atm."),
  // ---- specific senior and junior secondary topics (matched before the general ones below) ----
  C(/newton'?s laws|laws of motion|inertia|momentum|impulse/i, "Newton's laws of motion", "First law: an object stays at rest or moves steadily in a straight line unless an unbalanced force acts on it (inertia). Second law: force = mass × acceleration (F = ma). Third law: every action has an equal and opposite reaction. Momentum = mass × velocity, and in a collision the total momentum before equals the total momentum after.", ["Force is measured in newtons (N).", "Seat belts work because of inertia.", "Impulse = force × time = change in momentum."], "A 1,200 kg car accelerates at 2 m/s². Force = 1,200 × 2 = 2,400 N."),
  C(/work, energy and power|kinetic energy|potential energy|conservation of energy|simple machine|mechanical advantage|efficiency/i, "Work, energy, power and machines", "Work done = force × distance in the direction of the force (joules). Kinetic energy = ½mv²; potential energy = mgh. Energy is conserved: it changes form but the total stays the same. Power = work ÷ time (watts). A machine's efficiency = useful output ÷ input × 100%; no machine is 100% efficient because some energy is lost as heat.", ["Mechanical advantage = load ÷ effort.", "Velocity ratio = distance moved by effort ÷ distance moved by load."], "A 2 kg ball falls from 5 m: PE = 2 × 10 × 5 = 100 J, which becomes 100 J of kinetic energy just before it lands."),
  C(/waves|wave motion|transverse|longitudinal|frequency|wavelength|electromagnetic spectrum|reflection of waves|diffraction|interference/i, "Waves", "A wave carries energy without carrying matter. Transverse waves (light, water ripples) vibrate at right angles to the direction of travel; longitudinal waves (sound) vibrate along it. Speed v = frequency f × wavelength λ. Waves can be reflected, refracted, diffracted and can interfere. The electromagnetic spectrum runs from radio waves to gamma rays, all travelling at 3 × 10⁸ m/s in a vacuum.", ["Frequency is measured in hertz (Hz).", "Amplitude relates to loudness or brightness."], "A wave of frequency 50 Hz and wavelength 4 m travels at 50 × 4 = 200 m/s."),
  C(/current electricity|ohm|resistor|series and parallel|electric power|electrical energy|emf|internal resistance|kirchhoff/i, "Current electricity", "Ohm's law: V = IR. Resistors in series add: R = R₁ + R₂. In parallel: 1/R = 1/R₁ + 1/R₂. Electrical power P = VI = I²R and energy = power × time (kilowatt-hours at home). A cell has an e.m.f. E and internal resistance r, so the terminal voltage is V = E − Ir.", ["Ammeters go in series; voltmeters in parallel.", "Fuse rating should be just above normal current."], "A 60 W bulb on 240 V draws I = 60 ÷ 240 = 0.25 A."),
  C(/atomic structure|isotope|electron configuration|atomic number|mass number|radioactiv|nuclear/i, "Atomic structure", "An atom has a tiny nucleus of protons (positive) and neutrons (neutral), with electrons (negative) in energy levels around it. Atomic number = number of protons; mass number = protons + neutrons. Isotopes are atoms of the same element with different numbers of neutrons. Electrons fill shells 2, 8, 8, … so sodium (11) is 2,8,1. Radioactive atoms are unstable and emit alpha, beta or gamma radiation.", ["Neutral atom: protons = electrons.", "Half-life is the time for half the atoms to decay."], "Chlorine-35 and chlorine-37 are isotopes: both have 17 protons but 18 and 20 neutrons."),
  C(/chemical bonding|ionic bond|covalent bond|metallic bond|intermolecular|electronegativ|dative/i, "Chemical bonding", "Atoms bond to achieve full outer shells. Ionic bonding transfers electrons from a metal to a non-metal, forming oppositely charged ions (NaCl). Covalent bonding shares electrons between non-metals (H₂O, CH₄). Metallic bonding is a lattice of positive ions in a sea of free electrons, which explains conductivity and malleability. Ionic compounds have high melting points and conduct when molten or dissolved.", ["Metals lose electrons; non-metals gain or share.", "A dative bond: both shared electrons come from one atom."], "Sodium gives one electron to chlorine: Na⁺ and Cl⁻ attract to form NaCl."),
  C(/periodic table|periodicity|group \d|alkali metals|halogens|noble gases|transition metals|period \d/i, "The periodic table", "Elements are arranged by increasing atomic number. Columns are groups with similar properties because their atoms have the same number of outer electrons; rows are periods. Group 1 (alkali metals) are soft and very reactive; Group 7 (halogens) are reactive non-metals; Group 0 (noble gases) are unreactive with full outer shells. Reactivity increases down Group 1 and decreases down Group 7.", ["Metals on the left, non-metals on the right.", "Period number = number of occupied shells."], "Potassium reacts more violently with water than sodium because it loses its outer electron more easily."),
  C(/mole|molar mass|stoichiometr|avogadro|concentration of solution|molarity|limiting reagent|empirical formula|percentage composition|gas volume/i, "The mole and calculations", "The mole is the amount of substance containing 6.02 × 10²³ particles. Moles = mass ÷ molar mass. For gases at s.t.p., one mole occupies 22.4 dm³. Concentration (mol/dm³) = moles ÷ volume in dm³. Use the balanced equation to find the ratio of moles of reactants and products.", ["Molar mass is the relative formula mass in g/mol.", "Write the balanced equation first."], "How many moles are in 36 g of water (H₂O = 18)? 36 ÷ 18 = 2 mol."),
  C(/rates of reaction|reaction rate|catalyst|collision theory|activation energy|chemical equilibrium|le chatelier|energy changes|exothermic|endothermic|enthalpy|thermochemistry/i, "Rates, energy and equilibrium", "Reaction rate rises with higher concentration, temperature, surface area and the use of a catalyst, because more particles collide with enough energy. Exothermic reactions release heat (temperature rises); endothermic reactions absorb heat. In a reversible reaction at equilibrium the forward and backward rates are equal; Le Chatelier's principle says the system shifts to oppose any change.", ["A catalyst is not used up.", "ΔH is negative for exothermic reactions."], "Powdered marble reacts faster with acid than lumps because it has a larger surface area."),
  C(/organic chemistry|alkane|alkene|alkyne|alcohol|carboxylic|ester|homologous series|polymer|petroleum|hydrocarbon|isomer|functional group/i, "Organic chemistry", "Organic compounds contain carbon. Alkanes (CₙH₂ₙ₊₂) are saturated; alkenes (CₙH₂ₙ) have a C=C double bond and decolourise bromine water. Alcohols contain –OH, carboxylic acids –COOH, esters –COO–. A homologous series has the same functional group and a general formula. Crude oil is separated by fractional distillation; polymers are made from many monomers.", ["Name by the number of carbon atoms: meth, eth, prop, but, pent, hex.", "Isomers share a formula but differ in structure."], "Ethene (C₂H₄) reacts with hydrogen to form ethane (C₂H₆)."),
  C(/electrolysis|electrochem|redox|oxidation number|electrode|anode|cathode|electroplating|electrochemical series/i, "Electrolysis and redox", "Electrolysis uses electricity to decompose an ionic compound that is molten or in solution. Positive ions move to the cathode (reduction, gaining electrons); negative ions move to the anode (oxidation, losing electrons). OIL RIG: oxidation is loss, reduction is gain of electrons. Electroplating coats an object with metal by making it the cathode.", ["Inert electrodes: carbon or platinum.", "In the electrochemical series a more reactive metal displaces a less reactive one."], "Electrolysing copper(II) sulphate with copper electrodes deposits copper at the cathode."),
  C(/water\b.*(hardness|treatment)|hardness of water|water pollution|air pollution|environmental pollution|chemical industries|petroleum refining|extraction of metals|ores|fertiliser|soap|detergent|cement/i, "Industrial and environmental chemistry", "Chemistry serves industry: metals are extracted from ores (iron in a blast furnace, aluminium by electrolysis), soap is made by saponification of fats with an alkali, and fertilisers supply nitrogen, phosphorus and potassium. Hard water contains calcium and magnesium salts that form scum with soap; it is softened by boiling (temporary hardness) or ion exchange. Pollution from gases, oil and waste harms health and ecosystems.", ["Burning fossil fuels releases carbon dioxide and sulphur dioxide.", "Treat waste before releasing it."], "Temporary hard water is softened by boiling because calcium hydrogencarbonate decomposes to insoluble calcium carbonate."),
  C(/ecology|ecosystem|food web|nutrient cycle|carbon cycle|nitrogen cycle|population dynamics|succession|biome|adaptation|symbiosis|parasit|competition|conservation of natural/i, "Ecology in depth", "An ecosystem is a community of living things interacting with their non-living environment. Energy flows one way through food chains (about 10% passes up each level), while nutrients such as carbon and nitrogen cycle. Relationships include predation, competition, parasitism (one gains, the other is harmed), commensalism and mutualism (both gain). Succession is the gradual change in a community over time.", ["Producers are the base of the pyramid of numbers.", "Overgrazing and bush burning damage ecosystems."], "Nitrogen-fixing bacteria in the root nodules of beans and groundnuts enrich the soil."),
  C(/genetic|heredity|mendel|chromosome|\bdna\b|gene|allele|dominant|recessive|mutation|inheritance|punnett|variation/i, "Genetics and inheritance", "Characteristics are passed on by genes carried on chromosomes in the nucleus (made of DNA). We inherit one allele of each gene from each parent. A dominant allele (capital letter) shows even if only one copy is present; a recessive allele (small letter) shows only with two copies. A Punnett square predicts offspring. Mutations are changes in genes and give rise to variation.", ["Genotype is the gene combination; phenotype is how it shows.", "Human males are XY and females XX."], "Crossing two Tt (tall) plants gives TT : Tt : tt in the ratio 1 : 2 : 1, so three tall to one short."),
  C(/transport in plants|transpiration|osmosis|diffusion|active transport|xylem|phloem|translocation|water uptake|root hair/i, "Transport in living things", "Diffusion is the movement of particles from high to low concentration. Osmosis is the diffusion of water through a partially permeable membrane. Active transport moves substances against a concentration gradient using energy. In plants, xylem carries water and minerals upward, driven by transpiration (loss of water vapour through stomata); phloem carries food. In animals the blood system carries oxygen, food and wastes.", ["Root hairs increase surface area.", "Wilting happens when water loss exceeds uptake."], "A potato strip placed in strong salt solution loses water by osmosis and becomes limp."),
  C(/circulatory|blood|heart|pulse|arteries|veins|capillar|antibod|immunity|blood group|lymph|cardiovascular/i, "The circulatory system", "The heart is a muscular pump with four chambers. The right side sends blood to the lungs; the left sends oxygenated blood to the body. Arteries carry blood away from the heart under high pressure; veins return it (with valves); capillaries exchange materials with cells. Blood contains red cells (carry oxygen), white cells (defend), platelets (clot) and plasma.", ["Pulse rate is about 72 beats per minute at rest.", "Blood groups: A, B, AB and O."], "After exercise your heart beats faster to deliver more oxygen to the muscles."),
  C(/respiratory|gaseous exchange|lungs|alveol|breathing|ventilation|diaphragm|excretory|kidney|urine|liver|homeostasis|osmoregulation/i, "Breathing and excretion", "Air enters through the nose, trachea and bronchi to the alveoli in the lungs, where oxygen diffuses into the blood and carbon dioxide out. Breathing in: the diaphragm flattens and the ribs rise. The kidneys filter blood to form urine (urea, water and salts); the skin loses sweat; the lungs exhale carbon dioxide; the liver breaks down toxins. Homeostasis keeps conditions in the body steady.", ["Alveoli have thin walls and a rich blood supply.", "Dialysis replaces failed kidneys."], "Sweating cools the body as sweat evaporates from the skin."),
  C(/nervous system|reflex|brain|spinal cord|neuron|sense organ|eye|ear|endocrine|hormone|insulin|coordination/i, "Coordination and the senses", "The nervous system sends rapid electrical messages. The brain and spinal cord (central nervous system) receive information from receptors and send instructions to effectors (muscles and glands). A reflex action is automatic and fast, such as withdrawing the hand from heat. Hormones from endocrine glands (such as insulin from the pancreas) are chemical messengers that act more slowly.", ["Reflex arc: receptor, sensory neuron, relay neuron, motor neuron, effector.", "The eye focuses light on the retina; the ear detects sound and balance."], "Pupils get smaller in bright light to protect the retina."),
  C(/microorganism|micro-organism|bacteri|virus|fung|protozoa|disease|pathogen|vaccin|malaria|cholera|typhoid|hiv|sanitation|immunis/i, "Micro-organisms and disease", "Micro-organisms include bacteria, viruses, fungi and protozoa. Pathogens cause diseases: bacteria (cholera, typhoid, tuberculosis), viruses (HIV, influenza, COVID-19), protozoa (malaria, spread by the female Anopheles mosquito) and fungi (ringworm). Prevention includes clean water, sanitation, vaccination, treated nets and hygiene. Antibiotics kill bacteria but not viruses.", ["Vaccines prepare the immune system.", "Finish the course of any prescribed medicine."], "Cholera spreads through water contaminated with faeces, so boil or treat drinking water."),
  C(/simultaneous equation|quadratic equation|completing the square|quadratic formula|discriminant|roots of|nature of roots/i, "Quadratic and simultaneous equations", "A quadratic equation ax² + bx + c = 0 can be solved by factorising, completing the square or the formula x = (−b ± √(b² − 4ac)) / 2a. The discriminant b² − 4ac tells the roots: positive gives two real roots, zero one repeated root, negative none. Simultaneous equations are solved by substitution or elimination so both equations are true together.", ["Make the right-hand side zero first.", "Check by substituting back."], "x² − 5x + 6 = 0 factorises to (x − 2)(x − 3) = 0, so x = 2 or 3."),
  C(/linear graph|gradient|straight line|coordinate|cartesian|plotting|equation of a line|distance between two points|midpoint|graphs of/i, "Coordinate geometry and graphs", "A point is written (x, y). The gradient of a line through (x₁, y₁) and (x₂, y₂) is m = (y₂ − y₁) ÷ (x₂ − x₁). The equation of a straight line is y = mx + c, where c is the y-intercept. Parallel lines have equal gradients; perpendicular lines have gradients whose product is −1. The midpoint is the average of the coordinates.", ["Plot at least three points to check a line.", "Distance = √((x₂ − x₁)² + (y₂ − y₁)²)."], "The line through (0, 2) and (3, 8) has gradient 6 ÷ 3 = 2, so y = 2x + 2."),
  C(/circle theorem|chord|tangent|arc|sector|cyclic quadrilateral|segment|circles/i, "Circles", "Circumference = 2πr and area = πr². The length of an arc = (θ/360) × 2πr and the area of a sector = (θ/360) × πr². Circle theorems: the angle at the centre is twice the angle at the circumference; angles in the same segment are equal; the angle in a semicircle is 90°; opposite angles of a cyclic quadrilateral add up to 180°; a tangent is perpendicular to the radius.", ["Draw and label the diagram first.", "Give a reason for every angle you find."], "A sector of angle 90° in a circle of radius 14 cm has area ¼ × 22/7 × 14² = 154 cm²."),
  C(/mensuration|surface area|volume of|cone|cylinder|sphere|prism|pyramid|frustum/i, "Mensuration of solids", "Volume of a prism = area of cross-section × length. Cylinder: V = πr²h, curved surface area = 2πrh. Cone: V = ⅓πr²h, curved area = πrl where l is the slant height. Sphere: V = ⁴⁄₃πr³, surface area = 4πr². Pyramid: V = ⅓ × base area × height.", ["Keep units consistent.", "Volume is in cubic units; area in square units."], "A cylinder of radius 7 cm and height 10 cm has volume 22/7 × 49 × 10 = 1,540 cm³."),
  C(/variation|direct variation|inverse variation|joint variation|partial variation/i, "Variation", "If y varies directly as x, y = kx. If y varies inversely as x, y = k/x. Joint variation links more than two quantities, for example y = kxz. To solve, use the given values to find the constant k, then use the law to find the unknown.", ["Direct: both increase together.", "Inverse: one increases as the other decreases."], "If y varies inversely as x and y = 6 when x = 4, then k = 24, so when x = 8, y = 3."),
  C(/sequence|arithmetic progression|geometric progression|\bap\b|\bgp\b|sum of terms|nth term/i, "Sequences and series", "In an arithmetic progression (AP) each term adds a common difference d: nth term = a + (n − 1)d and the sum of n terms = n/2 [2a + (n − 1)d]. In a geometric progression (GP) each term is multiplied by a common ratio r: nth term = ar^(n−1) and the sum = a(rⁿ − 1)/(r − 1). A GP with |r| < 1 has a sum to infinity a/(1 − r).", ["Find a and d (or r) first.", "Check by listing the first few terms."], "AP 3, 7, 11, …: a = 3, d = 4, 10th term = 3 + 9 × 4 = 39."),
  C(/bearing|trigonometry|sine rule|cosine rule|angle of elevation|angle of depression|three-dimensional|compound angle|trigonometric ratio|identities/i, "Trigonometry and bearings", "In a right-angled triangle sin θ = opposite/hypotenuse, cos θ = adjacent/hypotenuse and tan θ = opposite/adjacent. For any triangle: sine rule a/sin A = b/sin B; cosine rule a² = b² + c² − 2bc cos A. Angles of elevation are measured up from the horizontal, depression down. A bearing is an angle measured clockwise from north, written with three figures (e.g. 045°).", ["Always draw a diagram.", "sin²θ + cos²θ = 1."], "A ladder 5 m long leans at 60° to the ground; its top is 5 sin 60° ≈ 4.33 m above the ground."),
  C(/matrices|determinant|inverse of a matrix|transformation|reflection|rotation|enlargement|translation|vectors?\b/i, "Matrices, vectors and transformations", "A matrix is multiplied row by column; the determinant of [a b; c d] is ad − bc and the inverse is (1/det)[d −b; −c a]. A vector has magnitude and direction; add vectors tip to tail. Transformations change a shape: translation (slide by a vector), reflection (mirror line), rotation (centre, angle, direction) and enlargement (centre and scale factor).", ["Reflection and rotation keep the size; enlargement does not.", "Area scale factor = (linear scale factor)²."], "Enlarging a triangle by scale factor 3 makes each side three times longer and the area nine times bigger."),
  C(/reading comprehension|inference|summary writing|précis|passage|figurative|tone and mood|lexis and structure|register|sentence structure/i, "Comprehension, summary and lexis", "Read the passage twice. Underline key points. Answer in complete sentences using your own words unless asked to quote. For summary, list the main points, join them in a coherent paragraph and stay within the word limit. Lexis questions ask the meaning of words or phrases as used in the passage, so give the meaning that fits the context.", ["Do not copy long stretches of the passage.", "Check spelling and punctuation."], "The phrase 'a storm of protest' means a very strong and sudden show of objection."),
  C(/oral english|syllable|consonant|schwa|cluster|contrast|phoneme|[ʊəɜʃʒθ]|vowel sound|consonant sound|stress|intonation|rhyme|phonetic|diphthong|monophthong|emphatic stress|word stress|homophone/i, "Oral English", "English has 20 vowel sounds (12 monophthongs and 8 diphthongs) and 24 consonant sounds. Word stress falls on one syllable (re-CORD as a verb, REC-ord as a noun). Emphatic stress highlights the word that carries the main meaning. Intonation rises in yes/no questions and falls in statements and wh-questions. Homophones sound alike but differ in meaning (sea/see, right/write).", ["Say words aloud and listen to the sounds.", "Use a dictionary's phonetic spelling."], "In 'I wanted TEA, not coffee', the stress is on tea to show contrast."),
  C(/lexis|idiom|proverb|synonym|antonym|word class|collocation|figures of speech|vocabulary development|prefix|suffix|root word/i, "Vocabulary and figures of speech", "Build vocabulary through reading and word parts. A prefix comes before a root (un-, re-, dis-) and a suffix after (-ness, -able, -ful). Synonyms share meaning; antonyms oppose it. Idioms have meanings that differ from the words (kick the bucket). Figures of speech include simile, metaphor, personification, hyperbole, irony, oxymoron, pun and euphemism.", ["Learn words in context, not alone.", "Keep a vocabulary notebook."], "'Her words were music to my ears' is a metaphor."),
  C(/essay|letter writing|formal letter|informal letter|speech writing|article|report writing|narrative essay|descriptive essay|argumentative|expository|debate|creative writing/i, "Writing for examinations", "Plan before you write: choose the type, audience and purpose; list three or four points; and decide the order. Write a clear introduction, one idea per paragraph with examples, and a firm conclusion. Use formal language for formal letters and speeches, vivid detail for descriptive writing, a clear time sequence for narratives, and balanced evidence for argumentative essays. Proofread for spelling, punctuation and concord.", ["Keep to the word limit.", "Begin and end letters correctly."], "A speech starts with a salutation: 'The Principal, members of staff, my fellow students, ladies and gentlemen'."),
  C(/demand|supply|equilibrium price|elasticity|price determination|market structure|monopoly|perfect competition|oligopoly/i, "Demand, supply and price", "The law of demand: as price rises, quantity demanded falls (other things equal). The law of supply: as price rises, quantity supplied rises. The market price settles where demand equals supply (equilibrium). A shift in demand comes from changes in income, tastes, population or the price of related goods. Elasticity measures how responsive quantity is to a price change: elastic if more than 1, inelastic if less than 1.", ["Movement along the curve = price change; shift = other factors.", "Necessities have inelastic demand."], "If a heavy rain destroys the tomato harvest, supply falls and the equilibrium price rises."),
  C(/national income|gdp|gnp|inflation|unemployment|money supply|monetary policy|fiscal policy|central bank|public finance|taxation|budget|balance of payments|international trade|exchange rate/i, "Macroeconomics", "National income is the total value of goods and services produced in a year (GDP). Inflation is a sustained rise in the general price level; unemployment is the state of being willing and able to work but without a job. The Central Bank of Nigeria controls money supply with monetary policy (interest rates, cash reserve ratio); government uses fiscal policy (taxes and spending). The balance of payments records a country's trade and money flows with the rest of the world.", ["Direct taxes: on income; indirect taxes: on goods.", "A depreciating naira makes imports dearer."], "If prices rise by 15% while wages rise by 5%, workers can buy less than before."),
  C(/mercantilism|colonialism|scramble for africa|berlin conference|slave trade|trans-saharan|world war|cold war|united nations|ecowas|african union|decolonisation|apartheid|pan-africanism/i, "African and world history", "Key events: the trans-Saharan and trans-Atlantic trades, the Berlin Conference of 1884–85 (partition of Africa), colonial rule, the two World Wars, the rise of nationalism and independence (Ghana 1957, Nigeria 1960), apartheid in South Africa, and regional cooperation through ECOWAS (1975) and the African Union (2002). Study causes, key people, events and effects.", ["Use dates and names correctly.", "Link causes to consequences."], "The Berlin Conference set rules for European powers to divide Africa without African representation."),
  C(/plot|setting|characterisation|theme|prose|poetry|drama|african literature|shakespeare|dramatic irony|soliloquy|sonnet|ode|elegy|ballad|stanza|imagery|symbolism/i, "Literature: how to analyse a text", "For prose, discuss plot, setting, characters, point of view and themes. For drama, look at acts and scenes, dialogue, conflict, stage directions, soliloquy (a character thinking aloud) and dramatic irony. For poetry, look at the speaker, imagery, sound devices (alliteration, assonance), rhyme and rhythm, and forms such as the sonnet (14 lines), ode, elegy and ballad. Always support points with short quotations.", ["Know your set texts closely.", "Link the writer's technique to its effect."], "In a sonnet the first eight lines (octave) often pose a problem that the last six (sestet) resolve."),
  C(/scientific method|laboratory safety|apparatus|measuring instruments|physical quantities|density|vernier|micrometer|significant figures|errors in measurement|accuracy|precision/i, "Measurement and scientific skills", "Measurement needs the right instrument and unit: a metre rule or vernier callipers for length, a balance for mass, a stopwatch for time, a measuring cylinder for volume. Density = mass ÷ volume (kg/m³). Report results with sensible significant figures and note sources of error. Accuracy means closeness to the true value; precision means closeness of repeated readings.", ["Read scales at eye level.", "Repeat readings and take the average."], "A block of mass 200 g and volume 50 cm³ has density 4 g/cm³."),
  C(/fraction|equivalent|mixed|improper/i, "Fractions", "A fraction shows part of a whole. The bottom number (denominator) says how many equal parts the whole is cut into; the top number (numerator) says how many parts we take. Equivalent fractions have the same value, for example 1/2 = 2/4 = 3/6. To add or subtract, the denominators must match.", ["Numerator over denominator.", "Multiply or divide top and bottom by the same number to make equivalent fractions.", "To add unlike fractions, find a common denominator first.", "Simplify the answer by dividing top and bottom by their highest common factor."], "Add 1/4 + 2/3. Common denominator 12: 3/12 + 8/12 = 11/12."),
  C(/decimal/i, "Decimals", "A decimal uses place value to the right of the point: tenths, hundredths, thousandths. 0.35 means 3 tenths and 5 hundredths. To add or subtract, line up the decimal points. To multiply, ignore the points, multiply, then place the point so the answer has as many decimal places as both numbers together.", ["Line up the points when adding and subtracting.", "0.5 = 1/2, 0.25 = 1/4, 0.75 = 3/4.", "To divide by 10, 100 or 1000, move the point left."], "2.4 × 0.3: 24 × 3 = 72; there are 2 decimal places in all, so the answer is 0.72."),
  C(/percent|profit|loss|interest|discount/i, "Percentages", "Percent means 'out of 100'. To find a percentage of an amount, divide by 100 and multiply. Profit is selling price minus cost price; percentage profit = profit ÷ cost price × 100. Simple interest = principal × rate × time ÷ 100.", ["25% = 1/4 = 0.25.", "Percentage change = change ÷ original × 100.", "Simple interest I = PRT/100."], "A shirt costing 2,000 naira is sold for 2,500 naira. Profit = 500. Percentage profit = 500/2,000 × 100 = 25%."),
  C(/ratio|proportion|rate/i, "Ratio and proportion", "A ratio compares quantities of the same kind and is written a:b. It can be simplified like a fraction. To share an amount in a ratio, add the parts, find one part, then multiply. In direct proportion, when one quantity is multiplied the other is too.", ["Simplify by dividing both parts by the same number.", "Share: total ÷ total parts = one part.", "Direct proportion: y = kx."], "Share 600 naira in the ratio 1:2:3. Total parts 6; one part 100; shares 100, 200, 300."),
  C(/area|perimeter|volume|surface/i, "Area, perimeter and volume", "Perimeter is the distance around a shape. Area is the surface inside it, in square units. Volume is the space inside a solid, in cubic units. Rectangle: area = length × width. Triangle: area = 1/2 × base × height. Circle: circumference = 2πr and area = πr².", ["Perimeter of a rectangle = 2(l + w).", "Area of a triangle = 1/2 × b × h.", "Volume of a cuboid = l × w × h.", "Use π = 22/7 or 3.14."], "A rectangle is 12 m by 5 m. Area = 60 m². Perimeter = 2(12 + 5) = 34 m."),
  C(/angle|triangle|polygon|parallel|geometry|quadrilateral/i, "Angles and shapes", "Angles are measured in degrees. Angles on a straight line add up to 180°, angles at a point add up to 360°. The three angles of any triangle add up to 180°. The angles of a quadrilateral add up to 360°. An isosceles triangle has two equal sides and two equal angles.", ["Right angle = 90°.", "Vertically opposite angles are equal.", "Sum of interior angles of an n-sided polygon = (n − 2) × 180°."], "Two angles of a triangle are 50° and 60°. The third is 180° − 110° = 70°."),
  C(/algebra|equation|expression|simultaneous|linear|inequalit|substitution|factoris/i, "Algebra", "In algebra, letters stand for unknown numbers. To solve an equation, do the same operation to both sides until the letter is alone. To simplify an expression, collect like terms. To expand brackets, multiply every term inside. Factorising is the reverse of expanding.", ["Keep the equation balanced.", "Like terms have the same letter part.", "a(b + c) = ab + ac."], "Solve 2x + 7 = 19. 2x = 12, so x = 6."),
  C(/indices|index|power|standard form|logarithm|surd/i, "Indices", "An index (power) tells how many times a number is multiplied by itself: 2⁴ = 2 × 2 × 2 × 2 = 16. Laws: a^m × a^n = a^(m+n); a^m ÷ a^n = a^(m−n); (a^m)^n = a^(mn); a⁰ = 1; a^(−n) = 1/a^n.", ["Add powers when multiplying like bases.", "Subtract powers when dividing.", "Any number to the power 0 is 1."], "Simplify 3² × 3⁴ = 3⁶ = 729."),
  C(/lcm|hcf|factor|multiple|prime/i, "Factors, multiples, HCF and LCM", "A factor divides a number exactly; a multiple is in its times table. A prime number has exactly two factors, 1 and itself. The HCF of two numbers is the biggest number that divides both. The LCM is the smallest number that both divide into.", ["Use prime factorisation to find HCF and LCM.", "2 is the only even prime.", "HCF × LCM = product of the two numbers."], "12 = 2² × 3 and 18 = 2 × 3². HCF = 2 × 3 = 6. LCM = 2² × 3² = 36."),
  C(/mean|median|mode|statistic|data|graph|chart|frequency/i, "Statistics", "Statistics is about collecting and presenting data. The mean is the total divided by the number of items. The median is the middle value when data is in order. The mode is the most frequent value. Data is shown in tables, bar charts, pictographs and pie charts.", ["Mean = sum ÷ count.", "Median: arrange in order first.", "A pie chart shows parts of a whole as angles out of 360°."], "Scores 4, 7, 7, 9, 13. Mean = 40 ÷ 5 = 8. Median = 7. Mode = 7."),
  C(/probability|chance|likely/i, "Probability", "Probability measures how likely an event is, from 0 (impossible) to 1 (certain). Probability = number of favourable outcomes ÷ total number of possible outcomes. The probabilities of all outcomes add up to 1.", ["P(not A) = 1 − P(A).", "Write probability as a fraction, decimal or percentage."], "A bag has 3 red and 7 blue balls. P(red) = 3/10."),
  C(/pythagoras|trigonometr|sine|cosine|bearing/i, "Right-angled triangles", "In a right-angled triangle the longest side, the hypotenuse, is opposite the right angle. Pythagoras' theorem: a² + b² = c². Trigonometry: sin = opposite/hypotenuse, cos = adjacent/hypotenuse, tan = opposite/adjacent.", ["SOH CAH TOA.", "Check that the hypotenuse is the longest side."], "Sides 3 and 4: c² = 9 + 16 = 25, so c = 5."),
  C(/\badd|subtract|counting|\bnumbers?\b|place value|multiplication|division|whole/i, "Whole numbers and the four operations", "Our number system uses place value: each digit's value depends on its position. We add, subtract, multiply and divide numbers, using BODMAS to decide the order. Multiplication is repeated addition and division is repeated subtraction (sharing).", ["Check subtraction by adding.", "Check division by multiplying.", "Estimate first by rounding."], "354 + 278 = 632. Check: 632 − 278 = 354."),
  C(/photosynth/i, "Photosynthesis", "Green plants make their own food. Chlorophyll in the leaves absorbs sunlight. The plant takes carbon dioxide from the air through tiny holes (stomata) and water from the soil through the roots, and makes glucose, releasing oxygen. Word equation: carbon dioxide + water → glucose + oxygen (in light).", ["Needs light, chlorophyll, carbon dioxide and water.", "Produces glucose and oxygen.", "Starch is the stored food."], "A plant kept in the dark cannot make starch, so a leaf test with iodine shows no blue-black colour."),
  C(/respiration|breath/i, "Respiration", "Respiration releases energy from food. Glucose reacts with oxygen to give carbon dioxide, water and energy. Breathing is how the body takes in oxygen and gives out carbon dioxide; respiration is the chemical release of energy inside cells.", ["Glucose + oxygen → carbon dioxide + water + energy.", "Living things respire all the time.", "Anaerobic respiration happens without oxygen."], "After running, you breathe faster because your muscles need more oxygen."),
  C(/food chain|food web|ecosystem|habitat|producer|consumer/i, "Food chains and ecosystems", "A food chain shows who eats whom and the flow of energy. It begins with a producer (a green plant) which is eaten by a primary consumer (herbivore), then a secondary consumer (carnivore). Decomposers break down dead matter and return nutrients to the soil.", ["Arrows point towards the eater.", "Energy decreases along the chain.", "An ecosystem is living things and their environment."], "Grass → grasshopper → frog → snake. The grasshopper is the primary consumer."),
  C(/digest|nutrition|food and|balanced diet|nutrient|teeth/i, "Digestion and nutrition", "Digestion breaks food into small soluble particles the body can absorb. Food passes through the mouth, oesophagus, stomach, small intestine (where most absorption happens) and large intestine. The seven classes of food are carbohydrates, proteins, fats and oils, vitamins, minerals, fibre and water.", ["Carbohydrates give energy.", "Proteins build and repair.", "Vitamins and minerals protect the body.", "A balanced diet has all classes in the right amounts."], "A child who eats mainly starch may lack protein and show stunted growth (kwashiorkor)."),
  C(/\bcells?\b|tissue|\borgans?\b|classification|living thing/i, "Cells and living things", "The cell is the basic unit of life. Plant and animal cells have a nucleus, cytoplasm and a cell membrane; plant cells also have a cell wall and chloroplasts. Cells form tissues, tissues form organs, and organs working together form a system. Living things are classified into groups by what they share.", ["Characteristics of life: move, respire, sense, grow, reproduce, excrete, nutrition.", "Cell → tissue → organ → system → organism."], "The heart is an organ made of muscle tissue; it belongs to the circulatory system."),
  C(/reproduct|life cycle|puberty|pollination|fertilis/i, "Reproduction", "Reproduction produces new individuals of the same kind. In flowering plants, pollination (the transfer of pollen to the stigma) is followed by fertilisation, and the ovary grows into a fruit with seeds. Humans reproduce sexually; the young develop and are born, and need care. Many insects pass through stages: egg, larva, pupa, adult.", ["Pollination is by wind, insects or water.", "Seed dispersal avoids overcrowding."], "A butterfly's life cycle: egg → caterpillar (larva) → pupa → adult."),
  C(/states? of matter|\bmatter\b|particle|melting|boiling|evaporat|condens/i, "States of matter", "Matter exists as solid, liquid or gas. Solid particles are packed closely and vibrate. Liquid particles slide past each other. Gas particles move freely and fill the container. Heating changes state: melting (solid to liquid), boiling or evaporation (liquid to gas); cooling reverses it by condensation and freezing.", ["Melting point of ice 0 °C; boiling point of water 100 °C.", "A physical change can be reversed."], "Water left in an open dish slowly evaporates even below 100 °C."),
  C(/mixture|separat|filtrat|distillat|solution|solvent|element|compound/i, "Mixtures and separation", "A mixture contains two or more substances that are not chemically joined. We separate mixtures by physical methods: filtration (insoluble solid from liquid), evaporation (soluble solid from solution), distillation (liquid from solution), magnet (iron from other solids), chromatography (coloured substances).", ["A solution is a solute dissolved in a solvent.", "Pure substances are elements or compounds."], "To get salt from sea water, evaporate the water."),
  C(/\bacids?\b|\bbases?\b|alkali|indicator|\bph\b|\bsalts?\b/i, "Acids, bases and salts", "Acids taste sour and turn blue litmus red; examples are lemon juice and vinegar. Bases that dissolve in water are alkalis; they feel soapy and turn red litmus blue. The pH scale runs from 0 to 14: below 7 acid, 7 neutral, above 7 alkaline. An acid and a base react to form a salt and water (neutralisation).", ["Never taste unknown chemicals.", "Indigestion is treated with a mild base."], "Hydrochloric acid + sodium hydroxide → sodium chloride + water."),
  C(/electric|current|circuit|conductor|cell|voltage|resistance/i, "Electricity", "An electric current is a flow of charge. A circuit needs a source, a closed path and a load. Conductors (metals) let current pass; insulators (plastic, rubber) do not. In a series circuit there is one path; in a parallel circuit there are several. Ohm's law: V = IR.", ["Current is measured in amperes, voltage in volts, resistance in ohms.", "A switch breaks the circuit."], "A 12 V battery across a 4 ohm resistor gives I = 12 ÷ 4 = 3 A."),
  C(/magnet/i, "Magnetism", "A magnet attracts iron, steel, nickel and cobalt. It has two poles, north and south. Like poles repel and unlike poles attract. A compass needle is a small magnet that points north. Magnets lose strength if heated, hammered or dropped.", ["Magnetic materials are attracted; non-magnetic are not.", "Field lines run from north to south outside the magnet."], "Two north poles pushed together repel each other."),
  C(/heat|temperature|thermal|conduction|convection|radiation/i, "Heat", "Heat is energy that flows from a hot object to a cooler one. It travels by conduction (through solids), convection (in liquids and gases, as warm fluid rises) and radiation (as waves, like sunlight). Temperature measures how hot something is, in degrees Celsius.", ["Metals are good conductors.", "Dark surfaces absorb and radiate heat best."], "A metal spoon in hot soup becomes hot by conduction."),
  C(/light|reflection|refraction|mirror|lens|shadow|colour/i, "Light", "Light travels in straight lines at very high speed. It is reflected by mirrors (the angle of incidence equals the angle of reflection) and refracted (bent) when it passes from one material to another. Opaque objects make shadows. White light splits into the colours of the rainbow.", ["Light travels faster than sound.", "A plane mirror gives an upright image the same size, laterally inverted."], "We see lightning before we hear thunder because light travels faster than sound."),
  C(/sound|vibrat|echo|pitch/i, "Sound", "Sound is made by vibrating objects and needs a material (solid, liquid or gas) to travel through; it cannot travel in a vacuum. A high-pitched sound has a high frequency. A loud sound has a large amplitude. An echo is sound reflected from a hard surface.", ["Sound travels fastest in solids, slowest in gases.", "Speed in air is about 340 m/s."], "If an echo returns after 2 s, the wall is 340 × 2 ÷ 2 = 340 m away."),
  C(/force|motion|friction|gravity|newton|speed|velocity|acceleration|momentum|pressure/i, "Forces and motion", "A force is a push or a pull, measured in newtons. Forces can change an object's speed, direction or shape. Friction opposes motion; gravity pulls objects to the Earth. Speed = distance ÷ time. Newton's second law: force = mass × acceleration.", ["Weight = mass × gravity (g ≈ 10 m/s²).", "Pressure = force ÷ area."], "A car travels 150 km in 2 hours. Speed = 75 km/h."),
  C(/energy|work|power|machine|lever|pulley|renewable/i, "Energy and machines", "Energy is the ability to do work, measured in joules. It changes from one form to another but is never lost. Work = force × distance moved. Simple machines (lever, pulley, inclined plane, wheel and axle) make work easier by trading force for distance.", ["Kinetic energy is energy of movement; potential energy is stored.", "Power = work ÷ time."], "Lifting a 20 N load through 3 m does 60 J of work."),
  C(/water cycle|rain|weather|climate|atmosphere|cloud/i, "Weather and the water cycle", "The Sun heats water, which evaporates and rises as vapour. Higher up it cools and condenses into clouds, then falls as rain, hail or snow (precipitation) and collects in rivers, lakes and seas. Weather is the day-to-day state of the air; climate is the pattern over many years. Instruments: thermometer, rain gauge, barometer, wind vane.", ["Nigeria has a wet and a dry season.", "Harmattan is a dry, dusty wind from the north-east."], "Clouds form when warm moist air rises and cools."),
  C(/soil|erosion|conservation|farm|crop|agricultur|horticulture|livestock/i, "Soil and farming", "Soil is made of rock particles, humus, air, water and living things. Sandy soil drains fast; clay holds water; loam is best for crops. Farmers prepare the land, sow, weed, protect crops from pests and harvest. Crop rotation and manure keep soil fertile; planting trees and terracing prevent erosion.", ["Humus comes from rotted plants and animals.", "Mixed farming combines crops and livestock."], "Maize is a cereal crop planted at the start of the rains."),
  C(/noun|pronoun|adjective|adverb|preposition|conjunction|parts of speech|article/i, "Parts of speech", "Words are grouped by their work. A noun names; a pronoun replaces a noun; a verb shows action or state; an adjective describes a noun; an adverb describes a verb, adjective or another adverb; a preposition shows position or relation; a conjunction joins; an interjection shows feeling.", ["Common, proper, collective and abstract nouns.", "Adjectives come before the noun they describe."], "In 'The tall boy ran quickly', tall is an adjective and quickly is an adverb."),
  C(/tense|verb|concord|agreement|voice|reported|direct and indirect/i, "Verbs, tenses and concord", "A verb must agree with its subject: 'The boy runs' but 'The boys run'. Tenses place an action in time: simple present, past and future; continuous (is running); perfect (has run). In reported speech the tense moves back: 'I am tired,' she said becomes She said that she was tired.", ["Learn irregular verbs.", "Keep tenses consistent."], "Neither of the boys is here (neither takes a singular verb)."),
  C(/punctuat|capital|comma|apostrophe|sentence|clause|phrase/i, "Sentences and punctuation", "A sentence has a subject and a verb and makes complete sense. Types: statement, question, command and exclamation. A clause has a subject and verb; a phrase does not. Punctuation marks guide the reader: full stop, comma, question mark, apostrophe, colon, semicolon and quotation marks.", ["Begin sentences and names with capital letters.", "Use an apostrophe for ownership and contractions."], "Ada's bag is on the table (the bag belongs to Ada)."),
  C(/comprehension|reading|passage|summary|inference/i, "Comprehension and summary", "To answer comprehension questions, read the passage twice, then read each question and find the answer in the text. Use your own words unless asked to quote. For a summary, pick only the main points, leave out examples and details, and write in complete sentences within the word limit.", ["Skim, then read carefully.", "Look for key words in the question.", "A summary is much shorter than the passage."], "Main idea of a paragraph is usually in its first or last sentence."),
  C(/essay|composition|\bletter\b|narrative|descriptive|argumentative|expository|\breport\b|speech work|debate/i, "Writing essays and letters", "A good essay has an introduction, body paragraphs and a conclusion. Plan first: choose your points and put them in order. Each paragraph has one main idea. A formal letter has the sender's address, date, receiver's address, salutation, heading, body, and a close (Yours faithfully or Yours sincerely). An informal letter is friendlier and has no receiver's address.", ["Plan, write, then check spelling and grammar.", "Argumentative essays give both sides before concluding."], "Yours faithfully is used when you begin with 'Dear Sir/Madam'."),
  C(/government|constitution|democracy|election|arms of|legislat|executive|judiciary|federal/i, "Government and democracy", "Government makes and enforces laws and provides services. Nigeria has three arms: the legislature makes laws, the executive carries them out, and the judiciary interprets them. In a democracy leaders are chosen in free and fair elections and citizens have rights and duties. The constitution is the supreme law.", ["Separation of powers prevents abuse.", "Everyone is equal before the law."], "The National Assembly (Senate and House of Representatives) is the federal legislature."),
  C(/citizen|\brights?\b|duty|duties|responsib|civic|honesty|corruption|human rights|peace|unity/i, "Citizenship, rights and duties", "A citizen belongs to a country and enjoys its rights while performing duties. Rights include life, dignity, fair hearing, freedom of expression and religion. Duties include obeying the law, paying tax, voting, protecting public property and respecting others. Honesty, integrity and tolerance build a peaceful society.", ["Rights come with responsibilities.", "Corruption hurts everyone."], "A student who returns lost property shows honesty."),
  C(/trade|market|commerce|business|money|bank|saving|entrepren|demand|supply|price|economy|production/i, "Trade, money and business", "People produce goods and services and exchange them. Money is a medium of exchange, a store of value and a measure of worth. Banks keep savings safe and give loans. Demand is how much buyers want at a price; supply is how much sellers offer. When demand rises and supply stays the same, prices rise.", ["Needs are essential; wants are not.", "Saving means keeping money for the future.", "Profit = revenue − cost."], "If many people want fuel and little is available, its price goes up."),
  C(/map|geograph|continent|ocean|latitude|longitude|compass|relief|settlement|population|nigeria|africa|vegetation|river/i, "Maps and geography", "A map is a drawing of an area seen from above. A scale lets us measure real distances. The compass points show direction: north, south, east and west. Latitudes run east-west (the equator is 0°); longitudes run north-south (the prime meridian is 0°). Nigeria has forest, savanna and Sahel vegetation belts.", ["The key explains map symbols.", "Contour lines show height."], "Scale 1 cm : 5 km means 4 cm on the map is 20 km on the ground."),
  C(/computer|hardware|software|input|output|storage|keyboard|mouse|operating system|word process|spreadsheet|presentation/i, "Computers", "A computer takes input, processes data and gives output. Hardware is the physical parts (monitor, keyboard, mouse, CPU); software is the programs. A word processor makes documents, a spreadsheet does calculations, and presentation software makes slides. Save work often and in clearly named folders.", ["Input: keyboard, mouse. Output: monitor, printer.", "The CPU is the brain of the computer."], "Typing a letter in a word processor and saving it as 'Letter to Principal'."),
  C(/internet|email|online|web|cyber|safety|digital citizen|network|algorithm|coding|programming|flowchart/i, "The internet, safety and coding", "The internet connects computers worldwide. A browser opens websites; email sends messages. Stay safe: use strong passwords, do not share personal details, and tell an adult about anything upsetting. An algorithm is a step-by-step set of instructions; a flowchart draws it with symbols; programs are algorithms written in a language the computer understands.", ["Be kind and honest online.", "Loops repeat steps; conditions choose between steps."], "Algorithm for making tea: boil water, add tea bag, wait, remove bag, add sugar."),
  C(/health|hygiene|first aid|disease|malaria|\bdrug|safety|exercise|sport|fitness|athlet|\bgames?\b/i, "Health, safety and fitness", "Good health means a healthy body, mind and surroundings. Wash hands with soap, drink safe water, sleep under a treated net, eat a balanced diet and exercise regularly. In first aid, stay calm, make the area safe, and call for help. Warm up before sport and cool down afterwards to prevent injury.", ["Prevention is better than cure.", "Say no to drugs.", "Know the emergency numbers."], "For a small burn, cool it under clean running water for at least ten minutes."),
  C(/bible|creation|adam|noah|abraham|moses|david|jesus|christ|prayer|parable|faith|gospel|church|psalm|prophet|paul/i, "Bible study", "Christian Religious Studies teaches from the Bible: God created the world and everything good; He made covenants with Abraham and Moses; the prophets called people to obey Him; and Jesus Christ taught about love, forgiveness and the kingdom of God, died and rose again. We learn lessons and apply them in daily life: obedience, faith, honesty, kindness and prayer.", ["Read the passage, say who is involved and what happened, then give the lesson.", "Parables are short stories with a spiritual meaning."], "The Good Samaritan teaches us to show kindness to everyone, even strangers."),
  C(/\bart\b|drawing|painting|colour|craft|pottery|printing|textile|dye|weav|sculpt/i, "Art and craft", "Art expresses ideas through line, shape, colour, texture and form. Primary colours (red, yellow, blue) mix to make secondary colours. Craft makes useful and decorative objects: pottery from clay, cloth patterns by tie and dye or batik, weaving, beadwork and carving. Plan with a sketch, make carefully and display with pride.", ["Warm colours are red, orange, yellow; cool are blue, green, purple.", "Wash tools and tidy up after work."], "Mixing blue and yellow paint makes green."),
  C(/music|song|rhythm|instrument|dance|drama|theatre|\bplay\b/i, "Music, dance and drama", "Music has rhythm (the beat pattern), melody (the tune) and harmony. Instruments are percussion (drums), string, wind and keyboard. Dance tells stories through movement. In drama, actors perform a script on a stage with costumes, props and sets; the director guides the play.", ["Practise together and listen to each other.", "Voice, posture and expression matter in drama."], "The talking drum is a percussion instrument that can imitate speech tones."),
  C(/midterm|mid-term|revision|examination|\btest\b|assessment|break/i, "Revision and assessment", "Revision means going back over what you have learnt so that you remember it. Read your notes, redraw diagrams from memory, redo worked examples and answer past questions. In a test, read each question carefully, plan your time, answer the easy ones first and check your work.", ["Revise a little every day.", "Test yourself instead of only re-reading.", "Sleep well before an exam."], "Make a one-page summary of each topic and use it for quick revision."),
  C(/nature of science|laboratory|apparatus|scientific method|measurement|physical quantit|units|science and/i, "The laboratory and scientific measurement", "Science studies the natural world by observation and experiment. In the laboratory we follow safety rules: wear protective clothing, never taste chemicals, and report breakages. Common apparatus includes beakers, test tubes, burettes, pipettes and thermometers. Measurements need units: length in metres, mass in kilograms, time in seconds, temperature in kelvin or degrees Celsius.", ["Observe, hypothesise, experiment, conclude.", "Fundamental quantities: length, mass, time, temperature, current.", "Always record units."], "A measuring cylinder reads volume; read it with your eye level with the bottom of the curve (meniscus)."),
  C(/chemistry|atom|periodic|bonding|ionic|covalent|mole|reaction|organic|hydrocarbon|metal|electrolysis|oxidation|reduction|equilibrium/i, "Atoms, bonding and reactions", "All matter is made of atoms, which have a nucleus of protons and neutrons with electrons in shells around it. Elements are arranged in the periodic table by atomic number. Atoms join by bonding: ionic bonds transfer electrons (sodium chloride), covalent bonds share electrons (water). In a chemical reaction, reactants form products and the total mass stays the same.", ["Atomic number = number of protons.", "A mole contains 6.02 × 10²³ particles.", "Balance equations so atoms are equal on both sides."], "2H₂ + O₂ → 2H₂O is balanced: four hydrogen and two oxygen atoms on each side."),
  C(/displacement|distance|kinematic|velocity|position|vector|scalar|projectile|circular motion/i, "Describing motion", "Distance is the total path travelled (a scalar). Displacement is the straight-line change in position with direction (a vector). Speed is distance ÷ time; velocity is displacement ÷ time. Acceleration is the rate of change of velocity. Equations of motion: v = u + at, s = ut + ½at², v² = u² + 2as.", ["Scalars have size only; vectors have size and direction.", "Slope of a distance-time graph is speed."], "A car accelerates from rest at 2 m/s² for 5 s: v = 0 + 2 × 5 = 10 m/s."),
  C(/growth|irritab|excretion|transport|circulat|heart|blood|skeleton|muscle|nervous|sense organ|human body|senses|body parts|plants around|plant|animals around/i, "The body, plants and animals", "Living things grow, respond to their surroundings (irritability) and remove waste (excretion). In humans the heart pumps blood through the blood vessels to carry oxygen and food to every cell. The skeleton supports the body and protects organs; muscles pull on bones to produce movement; the nervous system carries messages; the five senses are sight, hearing, smell, taste and touch. Plants have roots, stems, leaves and flowers, and animals can be grouped by how they move, feed and live.", ["Roots anchor the plant and absorb water.", "The brain controls the body.", "Eyes see, ears hear, nose smells, tongue tastes, skin feels."], "When you touch something hot, a message travels along nerves to your brain and you pull your hand away."),
  C(/scarcity|opportunity cost|economic|tools of|choice|production possibility|basic problems|factors of production|wealth|inflation|national income/i, "Basic economics", "Economics studies how people use limited resources to satisfy unlimited wants. Scarcity forces us to choose, and the next best alternative given up is the opportunity cost. The factors of production are land, labour, capital and enterprise, which earn rent, wages, interest and profit. Every society must decide what, how and for whom to produce.", ["Wants are unlimited; resources are limited.", "Every choice has an opportunity cost."], "If you spend 500 naira on a book instead of a game, the game is the opportunity cost."),
  C(/\bsets?\b|venn|subset|union|intersection|universal/i, "Sets", "A set is a collection of well-defined objects called elements. We write sets in braces: A = {1, 2, 3}. A subset has elements all found in another set. The union (A ∪ B) joins elements of both; the intersection (A ∩ B) holds the elements common to both. A Venn diagram shows sets as overlapping circles.", ["n(A ∪ B) = n(A) + n(B) − n(A ∩ B).", "The empty set has no elements."], "If A = {1, 2, 3} and B = {2, 3, 4}, then A ∩ B = {2, 3} and A ∪ B = {1, 2, 3, 4}."),
  C(/literary|literature|poetry|poem|prose|drama|novel|figure of speech|simile|metaphor|theme|character|plot|setting/i, "Literature and literary devices", "Literature is writing that is valued for its beauty and ideas: poetry, prose and drama. Study the plot (what happens), setting (where and when), characters, theme (the central message) and style. Literary devices include simile (a comparison with 'like' or 'as'), metaphor (a direct comparison), personification, irony, alliteration and imagery.", ["Support every point with evidence from the text.", "Poetry uses rhythm, rhyme and imagery."], "'The moon is a silver coin' is a metaphor; 'as bright as day' is a simile."),
  C(/french|saluer|greeting|se pr|bonjour|classroom words|vocabulaire|nombres/i, "Basic French", "French greetings: Bonjour (hello), Bonsoir (good evening), Salut (hi), Au revoir (goodbye), Merci (thank you), S'il vous plaît (please). To introduce yourself say Je m'appelle … (my name is …) and Comment vous appelez-vous? (what is your name?). Numbers: un, deux, trois, quatre, cinq, six, sept, huit, neuf, dix.", ["Nouns are masculine (le) or feminine (la).", "Practise speaking aloud."], "Bonjour, je m'appelle Ada. Comment ça va? (Hello, my name is Ada. How are you?)"),
  C(/alphabet|phonic|sound|cvc|rhyme|blend|spelling|dictation|handwriting|vowel/i, "Letters, sounds and spelling", "English has 26 letters: five vowels (a, e, i, o, u) and 21 consonants. Each letter has a sound, and sounds blend to make words: c-a-t makes cat. Learn to spell by saying the sounds, writing the word and checking it. Common spelling rule: i before e, except after c (receive).", ["Say the sound as you write.", "Practise a few words every day."], "b + a + g blends to make the word bag."),
  C(/device|phone|tablet|smartphone|mobile|gadget/i, "Digital devices", "Digital devices include computers, tablets, smartphones, calculators and smart TVs. They take in data, process it and show results. Use them safely: keep them away from water, do not use them for too long, charge them properly and ask an adult before downloading or sharing anything.", ["Every device has a screen, a processor and a way to input.", "Take regular breaks from screens."], "A smartphone can be a camera, a calculator and a clock at the same time."),
  C(/\btime\b|clock|calendar|days of the week|months|measuring|length|mass|capacity|pattern|money|naira|kobo|currency/i, "Measurement, time and money", "We measure length in millimetres, centimetres, metres and kilometres; mass in grams and kilograms; capacity in millilitres and litres. Time: 60 seconds make a minute, 60 minutes make an hour, 24 hours make a day, 7 days a week, 12 months a year. In Nigeria, 100 kobo make one naira. A pattern is a set of numbers or shapes that follows a rule.", ["1 m = 100 cm; 1 kg = 1,000 g; 1 l = 1,000 ml.", "To find change: amount paid − cost."], "A pen costs 150 naira. Paying 200 naira, the change is 50 naira."),
  C(/sewing|garment|fashion|tools and equipment|fabric|stitch|pattern making|textile|tailor|cosmetolog|beauty|hair|skin|nail|makeup/i, "Fashion, sewing and beauty skills", "Skilled workers learn the names and uses of their tools, keep them clean and use them safely. In sewing, tools include the tape measure, scissors, needles, pins and the sewing machine; the stages are measuring, drafting a pattern, cutting, tacking, stitching and pressing. In beauty and cosmetology, hygiene is essential: wash hands, sterilise tools and know the client's skin or hair type before any treatment.", ["Measure twice, cut once.", "Hygiene protects both worker and client.", "Business skills: pricing, record keeping and customer care."], "A tape measure is used to take body measurements before drafting a pattern."),
  C(/solar|photovoltaic|\bpv\b|inverter|battery|panel|renewable|installation/i, "Solar power systems", "A solar photovoltaic (PV) system turns sunlight into electricity. Its parts are solar panels, a charge controller, batteries to store energy, and an inverter that changes direct current (DC) to alternating current (AC) for appliances. Installers must work safely: wear protective gear, isolate the power before connecting, and fix panels securely facing the sun.", ["Panels in Nigeria face south and tilt about equal to the latitude.", "Never touch live terminals."], "A 100 W panel receiving 5 peak sun hours a day produces about 500 Wh of energy."),
  C(/history|colonial|empire|kingdom|independence|nationalism|slave|pre-colonial|civilisation|oyo|benin|kanem|sokoto|jihad/i, "Nigerian and world history", "History studies the past through evidence such as oral tradition, writings, artefacts and archaeology. Before colonial rule, Nigeria had organised states and empires such as Kanem-Bornu, the Hausa city-states, Oyo, Benin and the Igbo communities. Colonial rule began in the 19th century, nationalists campaigned for self-government, and Nigeria became independent on 1 October 1960.", ["Sources: oral, written, archaeological.", "Independence: 1 October 1960."], "Oral tradition is passed from one generation to the next by word of mouth."),
  C(/singular|plural|story|listening|writing my name|conversation|greetings|polite|poem|rhyme|oral/i, "Listening, speaking and word forms", "Good communication begins with listening carefully, then speaking clearly. A singular noun names one thing (book) and a plural names more than one (books). Most plurals add s; words ending in s, x, ch or sh add es (boxes); some change completely (child, children; man, men). Greet politely: Good morning, please, thank you, excuse me.", ["Listen first, then answer.", "Look at the end of the word to form the plural."], "One goat, two goats. One box, three boxes."),
  C(/typing|opening and closing|program|mouse|keyboard|paint|screen|save my work|using the/i, "Using a computer", "Use the mouse to point, click and drag, and the keyboard to type. To open a program, double-click its icon or choose it from the menu; to close it, click the X at the top corner. Always save your work with a clear name before you close. Sit properly, keep your fingers on the home keys and look at the screen, not the keys.", ["Save often.", "Ask for help before pressing unknown buttons."], "Type your name in a word processor, then choose Save and name the file 'My name'."),
  C(/paper folding|collage|cutting|pasting|modelling|clay|finger painting|colouring|display/i, "Simple craft activities", "Craft lets us make things with our hands. For paper work, fold along straight lines and crease firmly. For a collage, tear or cut pictures and colours and paste them to make a new picture. When modelling with clay, roll, pinch and press, and keep the clay moist. Always tidy up and wash your hands afterwards.", ["Use scissors carefully.", "Plan before you paste."], "Paste torn pieces of coloured paper onto card to make a tree."),
  C(/function|sequence|series|arithmetic progression|geometric progression|binomial|matrices|matrix|vector|differentiation|integration|calculus|limit|location|locus/i, "Functions, sequences and calculus ideas", "A function assigns exactly one output to each input, written f(x). An arithmetic sequence adds a constant difference: nth term = a + (n − 1)d. A geometric sequence multiplies by a constant ratio: nth term = ar^(n−1). Differentiation finds the rate of change: the derivative of x^n is nx^(n−1). Integration reverses it.", ["Sum of an arithmetic series = n/2 (2a + (n − 1)d).", "The gradient of a curve at a point is the derivative there."], "If f(x) = 3x + 2, then f(4) = 14."),
  C(/shape|solid|plane|roman|rounding|estimat|approximat|significant/i, "Shapes, Roman numerals and rounding", "Plane shapes are flat (circle, triangle, square, rectangle); solid shapes take up space (cube, cuboid, cylinder, cone, sphere). Roman numerals: I = 1, V = 5, X = 10, L = 50, C = 100. To round a number, look at the digit to the right of the place you need: if it is 5 or more, round up; if less than 5, leave as it is.", ["A cube has 6 faces, 12 edges, 8 corners.", "Round 347 to the nearest ten: 350."], "XLIV = 44 (XL = 40 and IV = 4)."),
  C(/home|house|rooms|clean|food|meal|cooking|kitchen|laundry|wash|cloth|dressing|garden|pets|safety at home/i, "Home and daily living", "A clean, safe home keeps the family healthy. Each room has its use: kitchen for cooking, bedroom for sleeping, sitting room for relaxing, bathroom for washing. Wash hands before cooking and eating, store food covered, sweep and dispose of waste properly, and keep sharp objects, medicine and chemicals out of children's reach.", ["Share the household chores.", "Cook food thoroughly and keep raw and cooked food apart."], "Wash vegetables in clean water before cooking them."),
  C(/ecolog|micro-organism|microorganism|bacteria|fungi|virus|conservation|pollution|environment|biodiversity|practical activities|closing/i, "Ecology and micro-organisms", "Ecology studies how living things relate to each other and their environment. Micro-organisms are living things too small to see without a microscope: bacteria, viruses, some fungi and protozoa. Some cause disease (malaria parasite, cholera bacteria); others are useful in making bread, yoghurt and medicines. We protect the environment by avoiding pollution, saving water and planting trees.", ["Wash hands and cook food to kill harmful germs.", "Conserve resources so they last."], "Yeast, a fungus, makes dough rise by producing carbon dioxide."),
  C(/accounting|ledger|trial balance|final account|double entry|journal|book-?keeping|balance sheet|depreciation|cash book/i, "Financial accounting", "Accounting records the money a business receives and spends. In double entry, every transaction is recorded twice: one account is debited and another is credited. Records begin in the journal and cash book, move to ledger accounts, and are summarised in a trial balance, then the income statement (profit or loss) and the statement of financial position.", ["Assets = Liabilities + Capital.", "Debit the receiver, credit the giver.", "The trial balance totals must agree."], "Goods bought for cash: debit Purchases, credit Cash."),
  C(/commerce|trade|retail|wholesale|insurance|advert|transport|warehous|tourism|banking|communication in business|documents/i, "Commerce and trade", "Commerce covers all activities that help goods move from producers to consumers: trade (wholesale and retail), banking, insurance, transport, warehousing, advertising and communication. Documents in trade include the invoice, receipt, credit note and delivery note. Insurance spreads the risk of loss among many people.", ["Wholesalers sell in bulk to retailers; retailers sell to consumers.", "Advertising informs and persuades buyers."], "A retailer buys from a wholesaler on credit and is sent an invoice showing the goods and prices."),
  C(/marketing|market|product|promotion|distribution|customer|brand|pricing|segmentation/i, "Marketing", "Marketing finds out what customers want and provides it at a profit. The marketing mix has four Ps: product, price, place (distribution) and promotion. Businesses study the market, divide customers into groups (segmentation), build a brand and keep customers satisfied.", ["Know your customer.", "Price must cover cost and give profit."], "A bakery that opens near a school and offers lunch-time snacks is matching product and place to its customers."),
  C(/farm|crop production|livestock|poultry|fish|cattle|goat|pig|rabbit|horticulture|vegetable|nursery|orchard|animal husbandry|feed|pest control|weed/i, "Crop and animal production", "Crop production steps: select land, clear and prepare it, plant good seed at the right time, weed, apply manure or fertiliser, control pests and diseases, harvest, store and market. Livestock needs housing, feeding, clean water, disease prevention (vaccination and sanitation) and good records. A nursery raises young plants before transplanting.", ["Keep records of costs and yields.", "Vaccinate before disease strikes.", "Rotate crops to protect the soil."], "Tomato seedlings are raised in a nursery for three to four weeks, then transplanted to the field."),
  C(/technical drawing|orthographic|isometric|projection|lettering|scale drawing|geometrical construction|drawing instruments|sectional/i, "Technical drawing", "Technical drawing communicates exact shapes and sizes. Tools include the T-square, set squares, compasses, scale rule and drawing pencils (H for hard, B for soft). Lines have meaning: thick for outlines, thin for dimensions, dashed for hidden details. Orthographic projection shows front, side and plan views; isometric drawing shows one view with three axes at 30 degrees.", ["Use a title block with the scale and your name.", "Keep pencils sharp and lines clean."], "To draw a 60 degree angle, use a compass and construct an equilateral triangle."),
  C(/food and nutrition|catering|meal planning|menu|cooking method|baking|kitchen equipment|food preservation|food hygiene|table setting|pastry|beverage/i, "Food, nutrition and catering", "Good food work starts with hygiene and planning. Cooking methods include boiling, steaming, frying, grilling, roasting and baking, each suited to different foods. Plan menus for balance, cost and occasion. Preserve food by drying, smoking, salting, refrigeration and canning. Serve and lay tables neatly, with cutlery arranged from the outside in.", ["Wash hands, surfaces and food.", "Cook meat thoroughly and keep raw and cooked food apart."], "A balanced lunch: jollof rice (carbohydrate), grilled fish (protein), and vegetable salad (vitamins)."),
  C(/gsm|phone repair|hardware repair|circuit board|soldering|multimeter|screen replacement|troubleshoot|computer repair|system unit|motherboard/i, "Electronics and device repair", "Repair work follows a safe routine: switch off and disconnect power, diagnose the fault, use the right tool, replace or repair the faulty part, test, and record the job. Tools include screwdriver sets, a multimeter for measuring voltage and continuity, a soldering iron and a hot-air station. Protect electronics from static electricity and never open a charged battery.", ["Document each repair.", "Handle batteries carefully.", "Be honest with customers about costs."], "A phone that will not charge may have a dirty charging port, a faulty cable or a bad battery; test the simplest causes first."),
  C(/government|executive|legislature|judiciary|political party|pressure group|constitutional development|federalism|separation of powers|public service|citizenship rights|colonial administration|indirect rule|military rule/i, "Government and politics", "Government is the institution that makes and enforces rules in a state. Constitutions set out how power is shared. Federalism divides power between a central government and states. Political parties compete for power, and pressure groups (such as labour unions) influence policy without seeking office. Nigeria's journey includes colonial indirect rule, the Richards, Macpherson and Lyttelton constitutions, independence in 1960, military rule, and the return to civilian democracy in 1999.", ["Rule of law: no one is above the law.", "Democracy needs free and fair elections."], "Indirect rule used traditional rulers to govern on behalf of the British, especially in the north."),
  C(/geograph|map reading|weather and climate|settlement|population|agriculture in nigeria|minerals|industries|transport and trade|latitude|relief|vegetation|rivers|drainage|natural resources|plate|volcan|erosion|rock/i, "Physical and human geography", "Geography studies the Earth's surface and how people use it. Physical geography covers landforms (mountains, plains, plateaus), rocks, rivers, weather and climate, and vegetation. Human geography covers settlements, population, farming, mining, industry and trade. Map reading uses scale, direction, grid references and contour lines to describe places.", ["Four-figure grid reference: eastings first, then northings.", "Contour lines close together mean a steep slope."], "Nigeria's population is unevenly spread, with dense settlement in the south-west and around Kano."),
  C(/christian religious|crs|prophet|elijah|isaiah|jeremiah|ezekiel|amos|hosea|kings of israel|exodus|covenant|early church|pentecost|apostle|epistle|corinth|romans|galatians|christian living|marriage|leadership/i, "Christian religious studies (senior)", "Senior CRS studies God's dealings with His people through the Old Testament (creation, covenant, Exodus, kingship and the prophets) and the New Testament (the life and teachings of Jesus, the early church and the letters of Paul). Each topic asks: what happened, who was involved, what was God's message, and how does it apply to Christian life today?", ["Quote the Bible reference when you can.", "Link every lesson to a moral value."], "Elijah on Mount Carmel teaches that people must choose whom they will serve and trust God completely."),
  C(/literature|prose|drama|poetry|novel|play|narrative technique|plot|theme|character|setting|tone|mood|style|african literature|shakespeare/i, "Studying a literary text", "To study a text, summarise the plot, describe the setting and characters, identify the themes, and notice how the writer uses language and structure. Back every point with a short quotation. In drama, consider stage directions, dialogue and conflict. In poetry, look at imagery, sound devices, rhythm and the poet's attitude.", ["Point, evidence, explanation (PEE).", "Compare how themes develop through the text."], "In Things Fall Apart, Okonkwo's fear of weakness leads to actions that cause his downfall."),
  C(/visual art|painting|drawing|sculpture|design|graphic|ceramic|pottery|textile|printmaking|perspective|composition|colour theory|art history/i, "Visual arts", "Visual art uses the elements of line, shape, colour, texture, form, space and value, arranged by principles such as balance, contrast, rhythm, emphasis and unity. Colour theory covers primary, secondary and tertiary colours and harmonies. Artists plan with sketches, choose materials, create and then evaluate their work.", ["Use a viewfinder to compose a picture.", "Learn about local and world art traditions."], "Mixing a primary colour with its neighbour on the colour wheel creates a tertiary colour."),
  C(/further mathematics|matrix|matrices|vector|binomial|complex number|polynomial|differential|integral|permutation|combination|conic|determinant|trigonometric identit|series|sequence/i, "Further mathematics", "Further mathematics extends algebra and calculus. A matrix is a rectangular array of numbers; the determinant of [a b; c d] is ad − bc. The binomial theorem expands (a + b)^n. Permutations count arrangements (nPr = n!/(n−r)!) and combinations count selections (nCr = n!/(r!(n−r)!)). Vectors have magnitude and direction.", ["Check dimensions before multiplying matrices.", "Differentiate to find gradients; integrate to find areas."], "How many ways can 3 prefects be chosen from 8 students? 8C3 = 56."),
  C(/entrepreneur|business plan|startup|small business|record keeping|capital|sources of finance|business studies|office practice|secretarial|keyboarding/i, "Business and entrepreneurship", "An entrepreneur spots a need, organises resources and takes the risk of starting a business. A business plan describes the idea, the market, the costs, the expected profit and how the owner will raise capital. Good record keeping shows whether the business makes a profit. Customer care and honesty build lasting trade.", ["Start small and grow carefully.", "Separate business money from personal money."], "A tailor who keeps a notebook of orders, costs and payments knows exactly how much profit each month brings."),
];

export function conceptFor(topic: string, subject = ""): Concept | null {
  const text = `${topic} ${subject}`;
  return CONCEPTS.find((c) => c.re.test(topic)) ?? CONCEPTS.find((c) => c.re.test(text)) ?? null;
}
